<script setup>
import { computed,onMounted,ref } from 'vue'
import { state,t,bridge,run,notify } from '../state.js'
import { personal,collectionDraft,ensurePersonalDraft,personalAction,releasePersonalDraft } from '../personal-state.js'
import { content,applyContent } from '../content-state.js'
import { textLength } from '../domain/validation.js'
import { newId } from '../domain/id.js'
import AppModal from './AppModal.vue'
import ActionButton from './ActionButton.vue'
import DraftImagePicker from './DraftImagePicker.vue'
import '../compose-collections.css'
const props=defineProps({id:String,publishing:Boolean}),emit=defineEmits(['close','saved','deleted']),d=collectionDraft(props.id),deleting=ref(false),deleteCommit=ref(newId())
if(!d.initialized){const x=content.collections.find(x=>x.id===props.id);if(x)Object.assign(d,{name:x.name,description:x.description,cover:x.coverId?{id:x.coverId,url:x.coverUrl}:null});d.initialized=true}
const photos=computed({get:()=>d.cover?[d.cover]:[],set:a=>d.cover=a[0]||null})
onMounted(()=>ensurePersonalDraft(d))
async function save(){let id=props.id,ok;if(id)ok=await personalAction('saveCollection',{id,draftId:d.draftId,commitId:d.commitId,name:d.name,description:d.description,coverId:d.cover?.id||null},{notice:'p2.collectionSaved'});else ok=await run('collection-save',async(signal,done)=>{const r=await bridge.call('content','createCollection',{draftId:d.draftId,commitId:d.commitId,name:d.name,description:d.description,coverId:d.cover?.id||null},{signal});await applyContent(r,signal);id=r.resultId;notify('toast.collectionCreated');done()},{critical:true});if(ok){delete personal.collectionDrafts[props.id||'new'];releasePersonalDraft(d);emit('saved',id)}}
async function remove(){if(await personalAction('deleteCollection',{id:props.id,commitId:deleteCommit.value},{notice:'p5.collectionDeleted'})){delete personal.collectionDrafts[props.id];emit('deleted')}}
</script>
<template><AppModal sheet :variant="publishing?'compose-collection':undefined" :blur-on-blank="publishing" :title="t(id?'p5.editCollection':publishing?'p2.createCollectionTitle':'p2.createCollection')" :closable="!state.ui.busy" @close="emit('close')"><div class="collection-editor"><DraftImagePicker v-model:photos="photos" :draft-id="d.draftId" :ready="d.ready" :max="1" :ordered="false" replace :replace-label="t('p5.editCover')" :label="t('p5.cover')"><template v-if="publishing" #add><img class="collection-cover-camera" src="/images/p2/collection-cover-camera.png" alt="" draggable="false"/><span>{{ t('p5.cover') }}</span></template></DraftImagePicker><ActionButton v-if="!d.ready" secondary @click="ensurePersonalDraft(d)">{{ t('retry') }}</ActionButton><div class="collection-edit-fields"><label class="sr-only" for="collection-name">{{ t('p2.collectionName') }}</label><input id="collection-name" v-model="d.name" :disabled="!!state.ui.busy" :placeholder="t('p2.collectionName')"/><label class="sr-only" for="collection-description">{{ t('p2.collectionDescription') }}</label><textarea id="collection-description" v-model="d.description" rows="4" :disabled="!!state.ui.busy" :placeholder="t('p2.collectionDescription')"/></div><p :class="publishing?'sr-only':'field-hint'">{{ t('p5.saveChangesHint') }}</p><p v-if="state.ui.error" class="error-banner" role="alert" :data-error-code="state.ui.error">{{ t('errors.'+state.ui.error) }}</p><button v-if="id" class="collection-delete-row" :disabled="!!state.ui.busy" @click="state.ui.error=null;deleting=true"><img src="/images/p5/collection-delete.png" alt=""/>{{ t('p5.deleteCollection') }}</button></div><template #headerAction><ActionButton class="purple-gradient sheet-save" :busy="state.ui.busy==='collection-save'||state.ui.busy==='personal-saveCollection'" :disabled="!!state.ui.busy||!d.ready||!d.name.trim()||textLength(d.name)>60||textLength(d.description)>300" @click="save">{{ t('save') }}</ActionButton></template></AppModal><AppModal v-if="deleting" centered variant="personal-confirm" :title="t('p5.deleteCollection')" :closable="!state.ui.busy" @close="deleting=false"><p>{{ t('p5.deleteCollectionHint') }}</p><strong>{{ content.collections.find(x=>x.id===id)?.name }}</strong><p v-if="state.ui.error" class="error-banner" :data-error-code="state.ui.error">{{ t('errors.'+state.ui.error) }}</p><template #footer><ActionButton secondary :disabled="!!state.ui.busy" @click="deleting=false">{{ t('cancel') }}</ActionButton><ActionButton :disabled="!!state.ui.busy" :busy="state.ui.busy==='personal-deleteCollection'" @click="remove">{{ t('p5.delete') }}</ActionButton></template></AppModal></template>
